```java
public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerFramework.ITriggerAction {

    public void execute(TriggerFramework.TriggerContextType contextType, 
                        List<SObject> records, 
                        Map<Id, SObject> oldMap) {

        // Identify records that need checking
        List<Contact> toCheck = new List<Contact>();

        for (SObject sobj : records) {
            Contact c = (Contact) sobj;
            if (c.AccountId == null || String.isBlank(c.Email)) continue;

            if (contextType == TriggerFramework.TriggerContextType.BEFORE_UPDATE) {
                Contact old = (Contact) oldMap.get(c.Id);
                if (old != null && old.Email == c.Email && old.AccountId == c.AccountId) {
                    continue;
                }
            }

            toCheck.add(c);
        }

        if (toCheck.isEmpty()) return;

        // Build lookup keys
        Set<Id> accountIds = new Set<Id>();
        Set<String> lowerEmails = new Set<String>();

        for (Contact c : toCheck) {
            accountIds.add(c.AccountId);
            lowerEmails.add(c.Email.toLowerCase());
        }

        // Single SOQL query
        List<Contact> existing = [
            SELECT Id, Email, AccountId 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND LOWER(Email) IN :lowerEmails
        ];

        // Collect all record IDs being processed (for self-exclusion on update)
        Set<Id> processingIds = new Set<Id>();
        for (Contact c : toCheck) {
            if (c.Id != null) processingIds.add(c.Id);
        }

        // Build set of existing conflict keys, excluding self
        Set<String> existingKeys = new Set<String>();
        for (Contact ex : existing) {
            if (processingIds.contains(ex.Id)) continue;
            String key = ex.AccountId + '|' + ex.Email.toLowerCase();
            existingKeys.add(key);
        }

        // Process in order: first one in batch is accepted
        Set<String> acceptedKeys = new Set<String>();

        for (Contact c : toCheck) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();

            if (existingKeys.contains(key) || acceptedKeys.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                acceptedKeys.add(key);
            }
        }
    }
}
```

